<script setup>
import {assessIncident} from '../../data/reportingRequirements.js'
import IncidentSupplement from '../reporter/IncidentSupplement.vue'
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useDemo} from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import {display,label,investigatorOptions} from './common.js'
const route=useRoute(),store=useDemo()
const event=computed(()=>store.getEvent(route.params.id))
const reviewReadiness=computed(()=>event.value?assessIncident(event.value,{stage:'review',hasCases:store.visibleRecords('cases').some(record=>record.eventId===event.value.id)}):{items:[],unresolved:[],explained:[],ready:true})
const reviewTabs=['overview','vessels','consequences','evidence','chronology']
const tab=ref('overview'),error=ref(''),remarks=ref(''),correction=ref(false)
watch(()=>[route.params.id,route.query.tab],()=>{tab.value=reviewTabs.includes(route.query.tab)?route.query.tab:route.query.tab==='lineage'?'evidence':'overview'},{immediate:true})
const reports=computed(()=>store.visibleRecords('reports').filter(r=>r.eventId===event.value?.id))
const cases=computed(()=>store.visibleRecords('cases').filter(r=>r.eventId===event.value?.id))
const actions=computed(()=>store.visibleRecords('actions').filter(r=>r.eventId===event.value?.id))
const openActions=computed(()=>actions.value.filter(a=>a.status!=='completed'))
const evidence=computed(()=>store.visibleRecords('evidence').filter(r=>r.eventId===event.value?.id||event.value?.evidenceIds?.includes(r.id)))
const lastCorrection=computed(()=>[...(event.value?.history||[])].reverse().find(h=>h.status==='correction_requested'))
const nextStep=computed(()=>({draft:'The report is being prepared. Complete the facts and submit it for review.',submitted:'Start review, check the reported facts, then validate or request a correction.',resubmitted:'The reporter has resubmitted. Compare the correction request with the updated facts.',under_review:'Check the five review sections, then validate or request a correction.',correction_requested:'A correction has been requested. The recorded instructions remain visible below.',validated:'The report is validated. Continue an investigation or follow-up when needed.'}[event.value?.status]||'Review the recorded information and choose the next task.'))
const informationToConfirm=computed(()=>{const e=event.value;if(!e)return[];const items=[];if(e.dateUnknown||!e.date)items.push('Occurrence date is unknown');if(e.timeUnknown||!e.time)items.push('Occurrence time is unknown');if(!e.place)items.push('Place description is missing');if(e.positionQuality==='unknown')items.push('Coordinates are not recorded');if(!(e.vessels||[]).length)items.push('No vessel particulars supplied');else if(e.vessels.some(v=>!v.officialNumber&&!v.imoNumber))items.push('A vessel has no recorded official or IMO number');const counts=['fatalities','missing','injured'].filter(k=>e.consequences?.[k]===null||e.consequences?.[k]===undefined||e.consequences?.[k]==='');if(counts.length)items.push('Unknown consequence counts: '+counts.join(', '));if(!e.sourceRef&&!evidence.value.length)items.push('No source reference or document is recorded');return items})
function transition(status){try{error.value='';store.transition(event.value.id,status,remarks.value);correction.value=false;remarks.value=''}catch(e){error.value=e.message}}
function assign(value){try{store.saveEvent({...event.value,investigatorId:value});error.value=''}catch(e){error.value=e.message}}
const kv=obj=>Object.entries(obj||{}).filter(([k])=>!['id','ownerId','officeId'].includes(k))
</script>
<template><div class="page-wrap case-workspace">
 <template v-if="event"><PageHeader :title="event.ref" :subtitle="`${event.type} · ${event.place||'Location unknown'}`" eyebrow="Incident workspace"><template #actions><q-btn flat no-caps label="Register" to="/admin/incidents"/><q-btn v-if="store.can('report',event)||store.can('review',event)" outline no-caps icon="edit" label="Edit particulars" :to="`/admin/incidents/${event.id}/edit`"/></template></PageHeader>
 <q-banner v-if="error" rounded class="bg-red-1 text-negative q-mb-md">{{error}}</q-banner>
 <section class="panel review-decision"><div class="row items-center q-gutter-sm q-mb-sm"><StatusBadge :status="event.status"/><span class="muted">{{event.dateUnknown?'Unknown date':display(event.date)}} · {{event.timeUnknown?'Unknown time':display(event.time)}}</span><q-space/><q-chip dense square>{{label(event.seriousness)}}</q-chip></div><div class="decision-content"><div><h2 class="section-title q-mb-xs">{{event.status==='validated'?'Review completed':'Review this report'}}</h2><p class="q-mb-none muted">{{nextStep}}</p></div><div class="decision-actions" v-if="store.can('review',event)"><q-btn v-if="['submitted','resubmitted'].includes(event.status)" color="primary" no-caps icon="fact_check" label="Start review" @click="transition('under_review')"/><q-btn v-if="event.status==='under_review'" outline color="primary" no-caps icon="edit_note" label="Request corrections" @click="correction=true"/><q-btn v-if="event.status==='under_review'" color="positive" no-caps icon="check_circle" label="Validate report" @click="transition('validated')"/><q-btn v-if="event.status==='validated'" flat color="primary" no-caps label="Reopen review" @click="transition('under_review')"/></div></div>
 <div v-if="lastCorrection&&['correction_requested','resubmitted','under_review'].includes(event.status)" class="correction-note q-mt-md"><strong>{{event.status==='resubmitted'?'Earlier correction request':'Correction instructions'}}</strong><p class="q-mb-xs ops-narrative">{{lastCorrection.remarks}}</p><span class="text-caption muted">{{lastCorrection.actorName||'Reviewer'}} · {{lastCorrection.at?new Date(lastCorrection.at).toLocaleString():'Time unknown'}}</span></div>
 <StaticSection v-if="informationToConfirm.length" icon="info_outline" :label="`Information to confirm (${informationToConfirm.length})`" class="confirm-details q-mt-sm"><p class="muted q-mb-sm">Review recorded unknowns and decide whether more information is needed. Required missing information must be addressed or explicitly explained before validation.</p><ul class="q-my-none"><li v-for="item in informationToConfirm" :key="item">{{item}}</li></ul></StaticSection>
 </section>
 <div class="review-layout"><section class="panel review-core"><div class="review-core-heading"><q-icon name="fact_check" color="primary" size="22px"/><h2 class="section-title q-my-none">Report facts</h2></div><q-tabs v-model="tab" align="left" active-color="primary" outside-arrows mobile-arrows><q-tab name="overview" label="Occurrence" no-caps/><q-tab name="vessels" :label="`Vessels (${event.vessels?.length||0})`" no-caps/><q-tab name="consequences" label="Consequences" no-caps/><q-tab name="evidence" :label="`Sources (${evidence.length})`" no-caps/><q-tab name="chronology" label="History" no-caps/></q-tabs><q-separator/>
 <q-tab-panels v-model="tab" animated>
  <q-tab-panel name="overview"><h3 class="section-title">What happened</h3><p class="ops-narrative">{{display(event.summary)}}</p><dl class="ops-kv"><template v-for="[k,v] in [['Date of Incident / Accident',event.dateUnknown?'Unknown':event.date],['Time of Incident / Accident (PHT)',event.timeUnknown?'Unknown':event.time],['Reported location',event.place],['Reporting account',store.state.users.find(u=>u.id===event.ownerId)?.name],['Reporting office',event.officeId],['Received date',event.receivedDate]]" :key="k"><dt>{{k}}</dt><dd>{{display(v)}}</dd></template></dl><h3 class="section-title q-mt-lg">Initial response</h3><p class="ops-narrative">{{display(event.initialActions)}}</p><h3 class="section-title q-mt-lg">Reported recommendations</h3><p class="ops-narrative">{{display(event.recommendations)}}</p><StaticSection icon="tune" label="Classification, position and office details" class="q-mt-lg"><dl class="ops-kv q-pa-sm"><template v-for="[k,v] in [['Type of Incident / Accident',event.type],['Secondary types',event.secondaryTypes?.join(', ')],['Impact types',event.impactTypes?.join(', ')],['Level of Maritime Accident (MARINA)',label(event.seriousness)],['Position Quality',event.positionQuality],['Latitude',event.lat],['Longitude',event.lon],['Area of Responsibility (AOR)',event.aor],['Homeport Office',event.homeport],['CPC Issuing Office',event.cpc],['Actual Issuing MRO',event.issuingOffice]]" :key="k"><dt>{{k}}</dt><dd>{{display(v)}}</dd></template></dl></StaticSection><IncidentSupplement :event="event"/></q-tab-panel>
  <q-tab-panel name="vessels"><section v-for="(v,i) in event.vessels" :key="v.id||i" class="vessel-review-card q-mb-md"><div class="row items-center q-gutter-sm q-mb-md"><q-icon name="directions_boat" color="primary" size="24px"/><div><h3 class="q-my-none">{{v.name||'Unnamed vessel'}}</h3><span class="muted text-caption">{{v.role||'Involved vessel'}}</span></div></div><dl class="ops-kv"><template v-for="[k,value] in [['Official / IMO number',[v.officialNumber||'Unknown',v.imoNumber||'Unknown'].join(' / ')],['Service / rig',[v.type||'Unknown',v.rigType||'Unknown'].join(' / ')],['Gross tonnage',v.grossTonnage],['Owner / operator',[v.owner||'Unknown',v.operator||'Unknown'].join(' / ')],['Voyage',[v.voyage?.origin||'Unknown origin',v.voyage?.destination||'Unknown destination'].join(' to ')]]" :key="k"><dt>{{k}}</dt><dd>{{display(value)}}</dd></template></dl><StaticSection label="Full vessel particulars" icon="unfold_more"><dl class="ops-kv q-pa-sm"><template v-for="[k,value] in kv(v)" :key="k"><dt>{{label(k.replace(/([A-Z])/g,' $1'))}}</dt><dd>{{typeof value==='object'?Object.entries(value||{}).map(([a,b])=>`${a}: ${display(b)}`).join(' · '):display(value)}}</dd></template></dl></StaticSection></section><p v-if="!event.vessels?.length" class="muted">Vessel particulars have not been supplied.</p></q-tab-panel>
  <q-tab-panel name="consequences"><div class="metric-grid"><div class="metric-card" v-for="key in ['fatalities','missing','injured','rescued']" :key="key"><div class="muted text-capitalize">{{key}}</div><div class="metric-value">{{display(event.consequences?.[key])}}</div></div></div><p class="muted">Counts apply once to this incident. Blank information is unknown; a recorded zero is a confirmed zero.</p><dl class="ops-kv"><template v-for="[k,v] in kv(event.consequences).filter(([k])=>!['fatalities','missing','injured','rescued'].includes(k))" :key="k"><dt>{{label(k.replace(/([A-Z])/g,' $1'))}}</dt><dd>{{display(v)}}</dd></template></dl></q-tab-panel>
  <q-tab-panel name="evidence"><div class="toolbar-row"><h3 class="section-title q-mb-none">Source information</h3><q-space/><q-btn flat no-caps color="primary" label="Manage evidence" :to="{path:'/admin/documents',query:{eventId:event.id}}"/></div><dl class="ops-kv"><template v-for="[k,v] in [['Source type',event.sourceType],['Source reference',event.sourceRef],['Received date',event.receivedDate]]" :key="k"><dt>{{k}}</dt><dd>{{display(v)}}</dd></template></dl><q-list separator><q-item v-for="e in evidence" :key="e.id"><q-item-section avatar><q-icon name="description"/></q-item-section><q-item-section><q-item-label>{{e.name}}</q-item-label><q-item-label caption>{{e.type}} · {{e.sourceRef||'No source reference'}} · {{e.notes}}</q-item-label></q-item-section><q-item-section side><StatusBadge :status="e.status"/></q-item-section></q-item></q-list><p v-if="!evidence.length" class="muted q-mt-md">No source document is linked.</p><StaticSection label="Source lineage" icon="account_tree" class="q-mt-lg"><dl class="ops-kv q-pa-sm"><template v-for="[k,v] in kv(event.sourceLineage)" :key="k"><dt>{{label(k)}}</dt><dd>{{display(v)}}</dd></template></dl><p v-if="!event.sourceLineage" class="muted q-pa-sm">No import lineage recorded.</p></StaticSection></q-tab-panel>
  <q-tab-panel name="chronology"><div class="timeline"><section v-for="(h,i) in [...(event.history||[])].reverse()" :key="h.id||i" class="q-mb-lg"><StatusBadge :status="h.status"/><p class="q-mb-xs">{{h.actorName||store.state.users.find(u=>u.id===h.actorId)?.name||'Recorded actor'}} · {{h.at?new Date(h.at).toLocaleString():'Time unknown'}}</p><p class="muted ops-narrative">{{h.remarks||'Status recorded'}}</p></section></div></q-tab-panel>
 </q-tab-panels></section>
 <aside class="context-column"><section class="panel"><h2 class="section-title">Continue this incident</h2><p class="muted">Review, investigation and follow-up stay linked to the same report.</p><q-btn v-if="store.can('investigate',event)" color="primary" no-caps icon="fact_check" label="Open investigation workbench" :to="`/admin/investigations/${event.id}`" class="full-width q-mb-md"/><q-select v-if="store.can('investigate',event)" :model-value="event.investigatorId" @update:model-value="assign" :options="investigatorOptions(store)" emit-value map-options outlined clearable label="Assigned investigator"/><StaticSection :label="`MAIC reports (${reports.filter(r=>r.type!=='spot').length})`" icon="description" class="q-mt-sm"><q-list separator><q-item v-for="r in reports.filter(r=>r.type!=='spot')" :key="r.id" clickable :to="{path:`/admin/investigations/${event.id}`,query:{reportId:r.id}}"><q-item-section><q-item-label>Form {{r.type}} · revision {{r.revision}}</q-item-label><q-item-label caption>{{r.date||'Date unknown'}}</q-item-label></q-item-section><q-item-section side><StatusBadge :status="r.status"/></q-item-section></q-item></q-list><p v-if="!reports.some(r=>r.type!=='spot')" class="muted q-pa-sm">No investigation revision recorded yet.</p></StaticSection><q-btn flat no-caps color="primary" label="Create an output" :to="{path:'/admin/reports',query:{eventId:event.id}}" class="q-mt-sm"/></section>
 <section class="panel" v-if="store.can('enforce',event)||cases.length"><div class="row justify-between items-center q-mb-md"><h2 class="section-title q-mb-none">Cases</h2><q-badge color="grey-3" text-color="dark">{{cases.length}}</q-badge></div><q-list separator><q-item v-for="c in cases" :key="c.id" clickable :to="`/admin/cases/${c.id}`"><q-item-section><q-item-label>{{c.caseNumber}}</q-item-label><q-item-label caption>{{c.party||'Party not recorded'}}</q-item-label><StatusBadge :status="c.status" class="q-mt-xs"/></q-item-section></q-item></q-list><p v-if="!cases.length" class="muted">No linked enforcement case.</p><q-btn v-if="store.can('enforce',event)" outline no-caps color="primary" icon="add" label="Create linked case" :to="{path:'/admin/cases',query:{eventId:event.id,new:'1'}}" class="full-width q-mt-md"/></section>
 <section class="panel"><div class="row justify-between items-center q-mb-md"><h2 class="section-title q-mb-none">Follow-up</h2><q-badge color="grey-3" text-color="dark">{{openActions.length}} open</q-badge></div><q-list separator><q-item v-for="a in openActions.slice(0,3)" :key="a.id"><q-item-section><q-item-label>{{a.title}}</q-item-label><q-item-label caption>{{store.state.users.find(u=>u.id===a.ownerId)?.name||'Unassigned'}} · Due {{a.dueDate||'not set'}}</q-item-label></q-item-section></q-item></q-list><p v-if="!openActions.length" class="muted">No outstanding follow-up action.</p><q-btn outline no-caps color="primary" label="Manage follow-up" :to="{path:'/admin/actions',query:{eventId:event.id}}" class="full-width q-mt-md"/></section></aside>
 </div>
 <q-dialog v-model="correction"><q-card style="width:550px;max-width:94vw"><q-card-section><div class="text-h6">Correction request</div><p class="muted q-mt-sm">Describe what needs to change so the reporting account can respond.</p><q-input v-model="remarks" outlined type="textarea" label="Required correction instructions" autofocus/></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn color="primary" no-caps label="Send request" :disable="!remarks.trim()" @click="transition('correction_requested')"/></q-card-actions></q-card></q-dialog>
 </template><section v-else class="panel"><h2>Incident unavailable</h2><p>This record does not exist or is outside your permitted scope.</p><q-btn color="primary" no-caps label="Return to register" to="/admin/incidents"/></section>
</div></template>
<style scoped>
.review-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:22px;align-items:start}.review-core,.context-column{min-width:0}.review-decision{border-color:#cbd5e1}.decision-content{display:flex;gap:20px;justify-content:space-between;align-items:center}.decision-actions{display:flex;flex-wrap:wrap;gap:10px;flex-shrink:0}.review-core-heading{display:flex;gap:10px;align-items:center;margin-bottom:12px}.correction-note{background:var(--ss-soft,#f1f5f9);border-left:3px solid #d69a38;border-radius:8px;padding:14px 16px}.confirm-details{border-top:1px solid var(--ss-border,#e2e5ea)}.confirm-details ul{padding-left:24px;line-height:1.8}.vessel-review-card{border:1px solid var(--ss-border,#e2e5ea);border-radius:10px;padding:18px}.ops-kv{display:grid;grid-template-columns:minmax(140px,1fr) 2fr;gap:10px 18px;margin:14px 0}.ops-kv dt{color:var(--ss-muted,#64748b)}.ops-kv dd{margin:0;overflow-wrap:anywhere}.ops-narrative{white-space:pre-wrap;line-height:1.7}.context-column .q-btn{white-space:normal}.case-workspace :deep(.q-card){min-width:0}
@media(max-width:1100px){.review-layout{grid-template-columns:minmax(0,1fr) 290px}.decision-content{align-items:flex-start;flex-direction:column}}
@media(max-width:850px){.review-layout{grid-template-columns:1fr}.context-column{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}.context-column .panel{margin-bottom:0}}
@media(max-width:600px){.ops-kv{grid-template-columns:1fr;gap:3px}.ops-kv dd{margin-bottom:12px}.decision-actions{width:100%}.decision-actions .q-btn{flex:1}.context-column{grid-template-columns:1fr}.vessel-review-card{padding:14px}}
</style>
